export function renderDashboard(): Response {
  const authAction =
    '<form action="/auth/logout" method="post"><button class="secondary" type="submit">Logga ut</button></form>';
  return new Response(DASHBOARD_HTML.replace("<!--AUTH_ACTION-->", authAction), {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "content-security-policy":
        "default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
      "x-content-type-options": "nosniff",
      "referrer-policy": "no-referrer",
    },
  });
}

export function renderDashboardStyles(): Response {
  return new Response(DASHBOARD_CSS, {
    headers: {
      "content-type": "text/css; charset=utf-8",
      "cache-control": "no-store",
      "x-content-type-options": "nosniff",
    },
  });
}

export function renderDashboardScript(): Response {
  return new Response(DASHBOARD_JS, {
    headers: {
      "content-type": "text/javascript; charset=utf-8",
      "cache-control": "no-store",
      "x-content-type-options": "nosniff",
    },
  });
}

const DASHBOARD_HTML = `<!doctype html>
<html lang="sv" data-theme="legacy">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark">
<meta name="theme-color" content="#04070e">
<title>Jobbautomation</title>
<link rel="stylesheet" href="/assets/dashboard.css">
</head>
<body>
<header class="page-head"><div><p class="eyebrow">Avkroken / Jobb</p><h1>Jobbautomation</h1><p class="muted">StudentConsulting → Arbetsförmedlingen · exakt 10 verifierade ansökningar per månad</p><p id="freshness" class="muted"></p></div><div class="page-actions"><label class="theme-control" for="theme-select"><span>Tema</span><select id="theme-select" aria-label="Tema"><option value="legacy">Legacy</option><option value="forest">Avkroken</option><option value="blackout">Blackout</option></select></label><!--AUTH_ACTION--></div></header>
<nav class="tabs" aria-label="Dashboard">
<a href="#overview" data-tab="overview">Översikt</a>
<a href="#applications" data-tab="applications">Ansökningar</a>
<a href="#runs" data-tab="runs">Körningar</a>
<a href="#report" data-tab="report">Aktivitetsrapport</a>
<a href="#system" data-tab="system">System</a>
</nav>
<main>
<section data-panel="overview"><div class="card">Laddar…</div></section>
<section data-panel="applications" hidden></section>
<section data-panel="runs" hidden></section>
<section data-panel="report" hidden></section>
<section data-panel="system" hidden></section>
</main>
<dialog id="runDialog"><div class="dialog-head"><h2 id="runTitle">Körningsdetaljer</h2><button id="closeRun" class="secondary">Stäng</button></div><div id="runBody"></div></dialog>
<script src="/assets/dashboard.js" defer></script>
</body>
</html>`;

const DASHBOARD_CSS = `:root{
  font-family:Inter,system-ui,sans-serif;color-scheme:dark;
  --bg:#04070e;--bg-soft:#050912;--panel:#09101e;--panel-2:#0d182c;
  --line:rgba(137,167,207,.18);--line-strong:rgba(137,167,207,.34);--text:#f5f3ee;--muted:#91a8c6;
  --control:#dce7f8;--control-text:#08111c;--accent:#7dd3fc;
  --ok:#78dba9;--warn:#ffd166;--bad:#ff7b7b;
  background:var(--bg);color:var(--text)
}
:root[data-theme="forest"]{
  --bg:#080b09;--bg-soft:#0c100d;--panel:#111713;--panel-2:#171f19;
  --line:#263129;--line-strong:#3b493e;--text:#f3f5f1;--muted:#a6b1aa;
  --control:#dce2dd;--control-text:#101612
}
:root[data-theme="blackout"]{
  --bg:#000;--bg-soft:#030303;--panel:#070707;--panel-2:#0d0d0d;
  --line:#1a1a1a;--line-strong:#333;--text:#f6f6f3;--muted:#b5b5b5;
  --control:#dedede;--control-text:#090909
}
*{box-sizing:border-box}
body{margin:0 auto;padding:24px;max-width:1280px;min-height:100vh;background:linear-gradient(180deg,var(--bg-soft),var(--bg) 34rem);color:var(--text)}
:root[data-theme="legacy"] body{background:radial-gradient(circle at 14% 8%,rgba(36,231,232,.11),transparent 27rem),radial-gradient(circle at 86% 18%,rgba(213,29,203,.10),transparent 30rem),radial-gradient(circle at 50% 100%,rgba(45,155,255,.08),transparent 35rem),linear-gradient(180deg,#050912 0%,#03060c 100%)}
:root[data-theme="legacy"] body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);background-size:42px 42px;mask-image:linear-gradient(to bottom,#000,transparent 82%)}
h1{margin:0;font-size:clamp(30px,5vw,44px)}h2{font-size:18px;margin:0 0 12px}
.page-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.page-actions{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap}.page-head form{margin:0}
.theme-control{display:grid;gap:3px;color:var(--muted);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em}.theme-control select{min-width:112px;background:var(--panel);color:var(--text);border:1px solid var(--line-strong);border-radius:9px;padding:9px 10px;text-transform:none;letter-spacing:normal}
.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.12em;color:var(--accent);margin:0 0 6px}.muted{color:var(--muted)}
.tabs{display:flex;gap:8px;overflow:auto;margin:24px 0}.tabs a{color:var(--text);text-decoration:none;border:1px solid var(--line);border-radius:999px;padding:9px 12px;white-space:nowrap}.tabs a[aria-current=page]{background:var(--control);color:var(--control-text)}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin:14px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:17px}.big{font-size:34px;font-weight:750}.ok{color:var(--ok)}.warn{color:var(--warn)}.bad{color:var(--bad)}.status{font-weight:750}
.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.button,button{border:0;border-radius:9px;padding:10px 14px;font-weight:700;cursor:pointer;background:var(--control);color:var(--control-text);text-decoration:none}.secondary{background:var(--panel-2)!important;color:var(--text)!important;border:1px solid var(--line)!important}.danger{background:transparent!important;color:var(--bad)!important;border:1px solid color-mix(in srgb,var(--bad) 55%,transparent)!important}button:disabled{opacity:.5;cursor:not-allowed}
.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line);vertical-align:top}.error{white-space:pre-wrap;color:var(--bad)}
.slots{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.slot{background:var(--panel-2);border:1px solid var(--line);border-radius:10px;padding:10px}.slot.uncertain{border-color:#a96832}.slot.verified{border-color:#39745b}.slot strong{display:block;font-size:20px}
.filters{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 12px}.filters input,.filters select{background:var(--panel-2);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:9px}.app-cards,.run-cards,.attempt-cards{display:none}.application-card,.run-card,.attempt-card{background:var(--panel-2);border:1px solid var(--line);border-radius:12px;padding:14px}.run-card .run-head,.attempt-card .run-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.run-card .run-meta,.attempt-card .run-meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}.run-card small,.attempt-card small{display:block;color:var(--muted);font-size:11px;margin-bottom:2px}.run-card .runDetail{width:100%;margin-top:10px}.application-card.needs-user-action{border-color:color-mix(in srgb,var(--warn) 55%,var(--line))}.application-card h3{font-size:16px;margin:8px 0 4px}.application-card h3 a{color:var(--text)}.app-meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}.app-meta span{min-width:0}.app-meta small{display:block;color:var(--muted);font-size:11px;margin-bottom:2px}.app-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:10px}.app-actions button{padding:8px 10px;font-size:12px}.app-action-result{flex-basis:100%;font-size:12px}.attention-note{border-color:color-mix(in srgb,var(--warn) 45%,var(--line))}.notice{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:9px 0}
.form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.field{display:grid;gap:5px}.field span,.check-row span{font-size:12px;font-weight:700;color:var(--muted)}.field input,.field textarea{width:100%;background:var(--panel-2);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:10px}.field textarea{min-height:76px;resize:vertical}.check-row{display:flex;align-items:center;gap:10px;padding:10px 0}.check-row input{width:18px;height:18px}.config-section{padding:14px 0;border-top:1px solid var(--line)}.config-section:first-child{border-top:0;padding-top:0}.config-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:14px}.source{font-size:11px;color:var(--muted)}.bankid-callout{border-color:var(--warn);margin:14px 0}.bankid-callout .button{display:inline-block}.config-note{font-size:12px;color:var(--muted);line-height:1.5}
.mono,code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;overflow-wrap:anywhere}
.activity-calendar{display:grid;gap:12px}.calendar-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.calendar-head h3{margin:0;text-transform:capitalize}.calendar-nav{padding:8px 11px}.calendar-weekdays,.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.calendar-weekdays span{text-align:center;color:var(--muted);font-size:11px;font-weight:700}.calendar-day,.calendar-blank{min-height:72px;border-radius:10px}.calendar-day{display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;padding:8px;background:var(--panel-2);color:var(--text);border:1px solid var(--line);font-weight:600}.calendar-day.has-applications:not(.download-ready){background:color-mix(in srgb,var(--ok) 14%,var(--panel-2));border-color:color-mix(in srgb,var(--ok) 60%,var(--line))}.calendar-day.download-ready{background:color-mix(in srgb,var(--accent) 18%,var(--panel-2));border-color:var(--accent)}.calendar-day.selected{outline:2px solid var(--text);outline-offset:1px}.calendar-number{font-size:14px}.calendar-count{font-size:11px;color:var(--ok)}.calendar-download-marker{font-size:10px;font-weight:800;color:var(--accent);letter-spacing:.06em}.calendar-legend{display:flex;gap:14px;flex-wrap:wrap;color:var(--muted);font-size:12px}.calendar-legend span{display:inline-flex;align-items:center;gap:6px}.calendar-dot{width:10px;height:10px;border-radius:999px;display:inline-block}.calendar-dot.application{background:var(--ok)}.calendar-dot.download{background:var(--accent)}.calendar-selection{border-top:1px solid var(--line);padding-top:12px}.calendar-selection p{margin:0 0 10px}
dialog{width:min(980px,calc(100vw - 28px));max-height:90vh;overflow:auto;background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:14px;padding:18px}dialog::backdrop{background:#000b}.dialog-head{display:flex;justify-content:space-between;align-items:center}.empty{padding:18px;color:var(--muted)}progress{width:100%}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@media(max-width:700px){body{padding:12px;max-width:100%;overflow-x:hidden}.calendar-day,.calendar-blank{min-height:60px}.calendar-day{padding:6px}.calendar-count{font-size:10px}.page-head{flex-direction:column}.page-actions{width:100%;align-items:stretch;justify-content:space-between}.page-actions form,.page-actions button,.theme-control,.theme-control select{min-width:0}.tabs{margin:18px -12px;padding:0 12px;scrollbar-width:none}.tabs::-webkit-scrollbar{display:none}.grid{grid-template-columns:1fr;gap:10px}.card{padding:14px}.slots{grid-template-columns:repeat(2,minmax(0,1fr))}.filters{display:grid;grid-template-columns:1fr;margin-bottom:14px}.filters input,.filters select{width:100%;min-width:0}.applications-table,.runs-table,.attempts-table{display:none}.app-cards,.run-cards,.attempt-cards{display:grid;gap:10px}.application-card,.run-card,.attempt-card{min-width:0}.app-meta,.run-card .run-meta,.attempt-card .run-meta{grid-template-columns:1fr 1fr}.app-actions{display:grid;grid-template-columns:1fr}.app-actions button{width:100%}.app-action-result{grid-column:1}.table-wrap{max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch}.table-wrap table{min-width:720px}.dialog-head{align-items:flex-start;gap:10px}.dialog-head h2{overflow-wrap:anywhere}dialog{width:calc(100vw - 20px);padding:14px}}`;

const DASHBOARD_JS = `var dashboard=null,configDirty=false,overviewSignature='',reportCalendarMonth='',reportCalendarSelectedDay='';
var themes=new Set(['legacy','forest','blackout']),defaultTheme='legacy',themeStorageKey='avkroken.theme',themeCookieName='avkroken_theme';
function savedTheme(){var c=document.cookie.split('; ').find(function(x){return x.indexOf(themeCookieName+'=')===0;});var v=c?c.split('=')[1]:'';if(themes.has(v))return v;try{v=localStorage.getItem(themeStorageKey)||'';}catch(_){}return themes.has(v)?v:'';}
function persistTheme(theme){try{localStorage.setItem(themeStorageKey,theme);}catch(_){}var denied=location.hostname==='denied.se'||location.hostname.endsWith('.denied.se');var domain=denied?'; Domain=.denied.se':'';var secure=location.protocol==='https:'?'; Secure':'';document.cookie=themeCookieName+'='+theme+'; Max-Age=31536000; Path=/; SameSite=Lax'+domain+secure;}
function applyTheme(value,save){var theme=themes.has(value)?value:defaultTheme;document.documentElement.dataset.theme=theme;var select=document.getElementById('theme-select');if(select)select.value=theme;var meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=theme==='legacy'?'#04070e':theme==='forest'?'#080b09':'#000000';if(save)persistTheme(theme);return theme;}
function initTheme(){var saved=savedTheme();applyTheme(saved||document.documentElement.dataset.theme||defaultTheme,Boolean(saved));var select=document.getElementById('theme-select');if(select)select.onchange=function(){applyTheme(select.value,true);};}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function badge(s){var cls=['verified','completed','submitted','captured','saved','sent','free'].includes(s)?'ok':['failed','errored'].includes(s)?'bad':'warn';return '<span class="status '+cls+'">'+esc(s)+'</span>';}
function when(v){if(!v)return '';var d=new Date(v);return Number.isNaN(d.valueOf())?esc(v):esc(new Intl.DateTimeFormat('sv-SE',{dateStyle:'medium',timeStyle:'short'}).format(d));}
function historicalReportGap(message){return typeof message==='string'&&(message.indexOf('Previous month ')===0||message.indexOf('Föregående månad ')===0);}
function reportState(r){return r&&r.status==='failed'&&historicalReportGap(r.last_error)?'saknar underlag':r&&r.status;}
function reportMessageClass(r){return r&&historicalReportGap(r.last_error)?'muted':'error';}
async function api(path,options){var r=await fetch(path,options);if(!r.ok){var text=await r.text(),message=text;try{message=JSON.parse(text).error||text;}catch(_){}throw new Error(message);}return r.json();}
function tab(name){if(!['overview','applications','runs','report','system'].includes(name))name='overview';document.querySelectorAll('[data-panel]').forEach(function(p){p.hidden=p.dataset.panel!==name;});document.querySelectorAll('[data-tab]').forEach(function(a){a.setAttribute('aria-current',a.dataset.tab===name?'page':'false');});}
function sourceLabel(s){return({deployment:'Deployment',dashboard:'Dashboard',mixed:'Blandat',missing:'Saknas'})[s]||s||'Saknas';}
function checkRow(label,ok,source){return '<div class="notice"><span>'+esc(label)+'<br><span class="source">'+esc(sourceLabel(source))+'</span></span><strong class="'+(ok?'ok':'bad')+'">'+(ok?'OK':'Saknas')+'</strong></div>';}
function dateOnly(v){if(!v)return '';var d=new Date(v);if(Number.isNaN(d.valueOf()))return String(v).slice(0,10);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);}
function localReportPanel(d){var r=d.runs.find(function(x){return x.status==='needs_user_auth'&&x.report_month===d.submissionReportMonth;});if(!r)return '';return '<div class="card bankid-callout"><p class="eyebrow">Föregående rapport '+esc(d.submissionReportMonth)+'</p><h2>Bekräfta sen inlämning</h2><p>Den här åtgärden gäller föregående månads rapport, inte '+esc(d.reportMonth)+'-aktiviteterna.</p><div class="toolbar"><a class="button" href="https://arbetsformedlingen.se/for-arbetssokande/mina-sidor/aktivitetsrapportera" target="_blank" rel="noopener noreferrer">Öppna aktivitetsrapporten</a><button id="reportSubmitted" class="secondary" type="button">Föregående rapport är inskickad</button><span id="reportSubmittedResult" class="muted"></span></div></div>';}
function inferredScope(i){var t=String(i.title||'').toLowerCase();if(/(^|[^a-zåäö])heltid([^a-zåäö]|$)/.test(t))return 'Heltid';if(/(^|[^a-zåäö])deltid([^a-zåäö]|$)/.test(t))return 'Deltid';return 'Kontrollera annonsen';}
function currentActivityPanel(d){var pending=d.reportActivities.find(function(i){return i.state!=='saved';});if(!d.reportActivities.length){if(d.verified>=d.target)return '<div class="card attention-note"><p class="eyebrow">Rapport '+esc(d.reportMonth)+'</p><h2>Aktiviteterna behöver förberedas</h2><p>De '+esc(d.target)+' verifierade jobben finns, men aktivitetskön är inte skapad ännu. Kör en manuell körning en gång för att förbereda den.</p></div>';return '';}if(!pending)return '<div class="card"><p class="eyebrow">Rapport '+esc(d.reportMonth)+'</p><h2>Alla '+esc(d.reportSaved)+' jobb är sparade</h2><p class="ok">Den aktuella månadens aktiviteter är registrerade. Själva rapporten skickas först i nästa rapportfönster.</p></div>';var place=pending.is_international?'Utomlands':'Sverige'+(pending.location?' – '+pending.location:'');var scope=inferredScope(pending);var source=pending.source_url?'<a class="secondary button" href="'+esc(pending.source_url)+'" target="_blank" rel="noopener noreferrer">Öppna annonsen</a>':'';return '<div class="card attention-note"><p class="eyebrow">Rapport '+esc(d.reportMonth)+' · '+esc(d.reportSaved)+'/'+esc(d.target)+' sparade</p><h2>Nästa sökta jobb</h2><p>Fyll samma värden i Arbetsförmedlingens formulär. Jobb håller reda på vilket av de '+esc(d.target)+' jobben du är på.</p><div class="notice"><span>Yrkesroll</span><strong>'+esc(pending.title||'')+'</strong></div><div class="notice"><span>Arbetsgivare</span><strong>'+esc(pending.employer||'')+'</strong></div><div class="notice"><span>Omfattning</span><strong>'+esc(scope)+'</strong></div><div class="notice"><span>Var finns jobbet?</span><strong>'+esc(place)+'</strong></div><div class="notice"><span>Svarade på annons?</span><strong>Ja</strong></div><div class="notice"><span>Datum sökt</span><strong>'+esc(dateOnly(pending.applied_at))+'</strong></div><div class="toolbar"><a class="button" href="https://arbetsformedlingen.se/for-arbetssokande/mina-sidor/aktivitetsrapportera/lagg-till-aktivitet" target="_blank" rel="noopener noreferrer">Öppna formuläret</a>'+source+'<button id="markReportItemSaved" class="secondary" type="button">Sparat – visa nästa jobb</button><span id="reportItemResult" class="muted"></span></div><p class="muted">Jobb-ID '+esc(pending.external_id)+'. När Arbetsförmedlingen visar att aktiviteten är sparad trycker du på “Sparat – visa nästa jobb”.</p></div>';}
function setupLocalReport(d){var b=document.getElementById('reportSubmitted');if(b)b.onclick=function(){confirmLocalReportSubmitted();};var pending=d.reportActivities.find(function(i){return i.state!=='saved';});var saved=document.getElementById('markReportItemSaved');if(saved&&pending)saved.onclick=function(){markCurrentReportItemSaved(d,pending);};}
function renderOverview(d){var reportActionRun=d.runs.find(function(x){return x.status==='needs_user_auth'&&x.report_month===d.submissionReportMonth;})||null;var signature=JSON.stringify({applicationMonth:d.applicationMonth,reportMonth:d.reportMonth,submissionReportMonth:d.submissionReportMonth,verified:d.verified,target:d.target,quotaUsed:d.quotaUsed,quotaSlots:d.quotaSlots,report:d.report,submissionReport:d.submissionReport,reportSaved:d.reportSaved,reportItems:d.reportItems,reportActivities:d.reportActivities,attention:d.attention,automaticMode:d.automaticMode,applicationWindowOpen:d.applicationWindowOpen,manualConfiguration:{studentConsultingCredentials:d.configuration.studentConsultingCredentials,studentConsultingAutoSubmit:d.configuration.studentConsultingAutoSubmit},reportActionRun:reportActionRun});if(signature===overviewSignature){setupLocalReport(d);setupManual(d);return;}overviewSignature=signature;var attention=d.attention.uncertainSlots+d.attention.failedRuns+d.attention.failedNotifications+d.attention.ambiguousReportItems+(d.attention.orphanedRuns||0)+(d.attention.expiredAuthRuns||0)+(d.attention.activeRun?1:0);var slots=d.quotaSlots.map(function(s){return '<div class="slot '+esc(s.state)+'"><strong>'+esc(s.slot_no)+'</strong>'+badge(s.state)+'<div class="mono">'+esc(s.application_id||'ledig')+'</div></div>';}).join('');var unresolved=d.attention.uncertainSlots?'<div class="card attention-note"><p class="eyebrow">Åtgärd krävs</p><h2>'+esc(d.attention.uncertainSlots)+' osäkra ansökningar</h2><p>De räknas inte bland de '+esc(d.target)+' godkända ansökningarna. Av säkerhetsskäl skickas inga nya ansökningar förrän de har kontrollerats eller markerats som inte inskickade.</p><a class="button" href="#applications">Hantera ansökningar</a></div>':'';var previousStatus=d.submissionReport?badge(reportState(d.submissionReport)):'<span class="muted">Inte registrerad</span>';var html='<div class="grid"><div class="card"><p class="eyebrow">'+esc(d.applicationMonth)+'</p><h2>Månadsmål</h2><div class="big">'+esc(d.verified)+'/'+esc(d.target)+'</div><progress max="'+d.target+'" value="'+d.verified+'"></progress><p class="muted">'+esc(d.quotaUsed)+'/'+esc(d.target)+' verifierade ansökningar</p></div><div class="card"><p class="eyebrow">Aktiviteter '+esc(d.reportMonth)+'</p><h2>Aktivitetsrapport</h2>'+(d.report?badge(reportState(d.report)):'<span class="muted">Inte skapad än</span>')+'<p>'+esc(d.reportSaved)+'/'+esc(d.reportItems||d.target)+' aktiviteter sparade</p><p class="muted">Föregående rapport '+esc(d.submissionReportMonth)+': '+previousStatus+'</p><p class="'+reportMessageClass(d.report)+'">'+esc(d.report&&d.report.last_error||'')+'</p></div><div class="card"><p class="eyebrow">Operativt</p><h2>Behöver uppmärksamhet</h2><div class="big '+(attention?'warn':'ok')+'">'+esc(attention)+'</div><p class="muted">Aktiva blockers och osäkra tillstånd</p></div></div><div class="grid"><div class="card"><h2>Godkända ansökningar</h2><p class="config-note">Endast verifierade StudentConsulting-ansökningar fyller de här '+esc(d.target)+' platserna.</p><div class="slots">'+slots+'</div></div><div class="card"><h2>Aktiva signaler</h2>'+signalRows(d)+'</div></div>'+unresolved+currentActivityPanel(d)+localReportPanel(d)+'<div class="grid"><div class="card"><h2>Manuell körning</h2><p>GitHub-inloggad, same-origin skyddad pipeline. Tillåten den 1:a–14:e.</p><div class="toolbar"><button id="manual" disabled>Kör nu</button><span id="manualResult" class="muted"></span></div></div><div class="card"><h2>Automatiskt säkerhetsläge</h2><div class="status ok">Aktivt</div><p>'+esc(d.automaticMode.schedule)+'</p></div></div>';document.querySelector('[data-panel=overview]').innerHTML=html;setupLocalReport(d);setupManual(d);}
function signalRows(d){var rows=[];if(d.attention.activeRun)rows.push(['Aktiv körning',badge(d.attention.activeRun.status)]);if(d.attention.orphanedRuns)rows.push(['Övergivna körningar','<strong class="warn">'+d.attention.orphanedRuns+'</strong>']);if(d.attention.expiredAuthRuns)rows.push(['Utgångna BankID-sessioner','<strong class="warn">'+d.attention.expiredAuthRuns+'</strong>']);if(d.attention.uncertainSlots)rows.push(['Osäkra ansökningar','<strong class="warn">'+d.attention.uncertainSlots+'</strong>']);if(d.attention.failedRuns)rows.push(['Senaste ansökningskörningen misslyckades','<strong class="bad">'+d.attention.failedRuns+'</strong>']);if(d.attention.failedNotifications)rows.push(['Notifieringsfel 30 dagar','<strong class="bad">'+d.attention.failedNotifications+'</strong>']);if(d.attention.ambiguousReportItems)rows.push(['Rapportposter i save_attempted','<strong class="warn">'+d.attention.ambiguousReportItems+'</strong>']);return rows.length?rows.map(function(r){return '<div class="notice"><span>'+r[0]+'</span>'+r[1]+'</div>';}).join(''):'<div class="empty">Inga kända blockers.</div>';}
function renderApplications(d){var html='<div class="card"><h2>Ansökningar</h2><p class="config-note"><code>needs_user_action</code> betyder att ett skickförsök kan ha gjorts men ännu inte har kunnat verifieras säkert. Använd Kontrollera igen, eller markera som ej inskickad om du har kontrollerat StudentConsulting själv.</p><div class="filters"><input id="appSearch" type="search" placeholder="Sök jobb, arbetsgivare, Jobb-ID"><select id="appStatus"><option value="">Alla statusar</option><option>verified</option><option>submitted</option><option>applying</option><option>queued</option><option>needs_user_action</option><option>failed</option></select></div><div class="table-wrap applications-table"><table><thead><tr><th>Status</th><th>Jobb</th><th>Ort</th><th>Datum</th><th>Run</th><th>Evidens</th><th>Fel</th><th>Åtgärd</th></tr></thead><tbody id="appRows"></tbody></table></div><div id="appCards" class="app-cards"></div></div>';document.querySelector('[data-panel=applications]').innerHTML=html;function rows(){var q=document.getElementById('appSearch').value.toLowerCase(),s=document.getElementById('appStatus').value;var items=d.applications.filter(function(a){return(!s||a.status===s)&&(!q||[a.title,a.employer,a.external_id,a.location].join(' ').toLowerCase().includes(q));});document.getElementById('appRows').innerHTML=items.length?items.map(appRow).join(''):'<tr><td colspan="8" class="empty">Inga träffar.</td></tr>';document.getElementById('appCards').innerHTML=items.length?items.map(appCard).join(''):'<div class="empty">Inga träffar.</div>';setupApplicationActions();}document.getElementById('appSearch').oninput=rows;document.getElementById('appStatus').onchange=rows;rows();}
function applicationIssue(a){if(a.status==='needs_user_action'&&a.error_code==='APPLICATION_UNKNOWN')return 'Skickförsöket gjordes, men StudentConsulting kunde inte bekräfta Jobb-ID '+a.external_id+' i Ansökningar. Den räknas därför inte som godkänd.';return [a.error_code,a.error_message].filter(Boolean).join(' ');}
function applicationActions(a){if(a.status!=='needs_user_action')return '';return '<div class="app-actions"><button class="secondary appRecheck" type="button" data-id="'+esc(a.id)+'">Kontrollera igen</button><button class="danger appNotSubmitted" type="button" data-id="'+esc(a.id)+'" data-job-id="'+esc(a.external_id)+'">Markera ej inskickad</button><span class="app-action-result muted" data-result-id="'+esc(a.id)+'"></span></div>';}
function appRow(a){return '<tr><td>'+badge(a.status)+'</td><td><a href="'+esc(a.source_url)+'" target="_blank" rel="noopener noreferrer">'+esc(a.title)+'</a><br><span class="muted">'+esc(a.employer||'')+'</span><br><code>'+esc(a.external_id)+'</code></td><td>'+esc(a.location||a.country_code||'')+'</td><td>'+when(a.verified_at||a.applied_at||a.created_at)+'</td><td><code>'+esc(a.automation_run_id||'')+'</code></td><td>'+esc(a.evidence_count||0)+'</td><td class="error">'+esc(applicationIssue(a))+'</td><td>'+applicationActions(a)+'</td></tr>';}
function appCard(a){var issue=applicationIssue(a);return '<article class="application-card '+(a.status==='needs_user_action'?'needs-user-action':'')+'">'+badge(a.status)+'<h3><a href="'+esc(a.source_url)+'" target="_blank" rel="noopener noreferrer">'+esc(a.title)+'</a></h3><div class="muted">'+esc(a.employer||'')+'</div><div class="app-meta"><span><small>Jobb-ID</small><code>'+esc(a.external_id)+'</code></span><span><small>Ort</small>'+esc(a.location||a.country_code||'')+'</span><span><small>Datum</small>'+when(a.verified_at||a.applied_at||a.created_at)+'</span><span><small>Evidens</small>'+esc(a.evidence_count||0)+'</span></div>'+(issue?'<p class="error">'+esc(issue)+'</p>':'')+applicationActions(a)+'</article>';}
function setupApplicationActions(){document.querySelectorAll('.appRecheck').forEach(function(b){b.onclick=function(){resolveApplicationAttention(b.dataset.id,'recheck',b.dataset.jobId||'');};});document.querySelectorAll('.appNotSubmitted').forEach(function(b){b.onclick=function(){resolveApplicationAttention(b.dataset.id,'not-submitted',b.dataset.jobId||'');};});}
function setApplicationActionState(id,message,busy){document.querySelectorAll('.appRecheck,.appNotSubmitted').forEach(function(b){if(b.dataset.id===id)b.disabled=busy;});document.querySelectorAll('.app-action-result').forEach(function(out){if(out.dataset.resultId===id)out.textContent=message||'';});}
async function resolveApplicationAttention(id,action,jobId){if(action==='not-submitted'&&!confirm('Bekräfta att Jobb-ID '+jobId+' inte skickades. Den osäkra spärren släpps och ansökan räknas inte.'))return;setApplicationActionState(id,action==='recheck'?'Kontrollerar StudentConsulting…':'Uppdaterar…',true);try{var r=await api('/api/applications/'+encodeURIComponent(id)+'/'+action,{method:'POST'});setApplicationActionState(id,r.message||'Klart.',false);if(r.changed)setTimeout(load,450);}catch(e){setApplicationActionState(id,'Kunde inte uppdatera: '+e.message,false);}}
function reportOnlyRunFailure(r){return r.status==='failed'&&Number(r.verified_count)>=Number(r.target_count)&&historicalReportGap(r.last_error);}
function runState(r){return reportOnlyRunFailure(r)?'completed':r.orphaned?'orphaned':r.expiredAuth?'expired_auth':r.status;}
function runError(r){return r.last_error||r.probe_error||(r.orphaned?'WORKFLOW_ORPHANED: workflow-koppling saknas och ingen ansökningsaktivitet observerades.':r.expiredAuth?'BANKID_HANDOFF_EXPIRED: BankID-sessionen har gått ut.':'');}
function runMessageClass(r){return reportOnlyRunFailure(r)?'muted':'error';}
function runRow(r){return '<tr><td>'+when(r.started_at)+'</td><td>'+esc(r.mode)+'</td><td>'+badge(runState(r))+'</td><td>'+esc(r.application_month)+'</td><td>'+esc(r.verified_count)+'/'+esc(r.target_count)+'</td><td>'+(r.probe_status?badge(r.probe_status):'')+'</td><td class="'+runMessageClass(r)+'">'+esc(runError(r))+'</td><td><button class="secondary runDetail" data-id="'+esc(r.id)+'">Detaljer</button></td></tr>';}
function runCard(r){var error=runError(r);return '<article class="run-card"><div class="run-head"><span>'+badge(runState(r))+'</span><span class="muted">'+when(r.started_at)+'</span></div><div class="run-meta"><span><small>Läge</small>'+esc(r.mode)+'</span><span><small>Månad</small>'+esc(r.application_month)+'</span><span><small>Verifierade</small>'+esc(r.verified_count)+'/'+esc(r.target_count)+'</span><span><small>Probe</small>'+(r.probe_status?badge(r.probe_status):'<span class="muted">—</span>')+'</span></div>'+(error?'<p class="'+runMessageClass(r)+'">'+esc(error)+'</p>':'')+'<button class="secondary runDetail" data-id="'+esc(r.id)+'">Detaljer</button></article>';}
function renderRuns(d){var rows=d.runs.map(runRow).join(''),cards=d.runs.map(runCard).join('');document.querySelector('[data-panel=runs]').innerHTML='<div class="card"><h2>Senaste körningar</h2><div class="table-wrap runs-table"><table><thead><tr><th>Start</th><th>Läge</th><th>Status</th><th>Månad</th><th>Verifierade</th><th>Probe</th><th>Notering</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="run-cards">'+(cards||'<div class="empty">Inga körningar.</div>')+'</div></div>';document.querySelectorAll('.runDetail').forEach(function(b){b.onclick=function(){openRun(b.dataset.id);};});}
function calendarDateKey(v){if(!v)return '';var d=new Date(v);if(Number.isNaN(d.valueOf()))return String(v).slice(0,10);var parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d),out={};parts.forEach(function(p){out[p.type]=p.value;});return out.year+'-'+out.month+'-'+out.day;}
function calendarMonthLabel(month){var p=String(month).split('-'),d=new Date(Date.UTC(Number(p[0]),Number(p[1])-1,1));return new Intl.DateTimeFormat('sv-SE',{month:'long',year:'numeric',timeZone:'UTC'}).format(d);}
function activityCalendarMonths(d){var values=new Set([d.reportMonth]);(d.activityCalendar||[]).forEach(function(x){if(x.report_month)values.add(x.report_month);});(d.activityExports||[]).forEach(function(x){if(x.report_month)values.add(x.report_month);});return Array.from(values).sort();}
function renderActivityCalendar(d){var months=activityCalendarMonths(d);if(!reportCalendarMonth||months.indexOf(reportCalendarMonth)<0)reportCalendarMonth=d.reportMonth;var month=reportCalendarMonth,idx=months.indexOf(month),parts=month.split('-'),year=Number(parts[0]),monthNo=Number(parts[1]),daysInMonth=new Date(Date.UTC(year,monthNo,0)).getUTCDate(),firstWeekday=(new Date(Date.UTC(year,monthNo-1,1)).getUTCDay()+6)%7,counts={};(d.activityCalendar||[]).filter(function(x){return x.report_month===month;}).forEach(function(x){var key=calendarDateKey(x.applied_at);counts[key]=(counts[key]||0)+1;});var exportRow=(d.activityExports||[]).find(function(x){return x.report_month===month;})||null,readyDay=exportRow?calendarDateKey(exportRow.ready_at):'',cells='';for(var blank=0;blank<firstWeekday;blank+=1)cells+='<div class="calendar-blank" aria-hidden="true"></div>';for(var day=1;day<=daysInMonth;day+=1){var key=month+'-'+String(day).padStart(2,'0'),count=counts[key]||0,ready=key===readyDay,selected=key===reportCalendarSelectedDay,classes='calendar-day'+(count?' has-applications':'')+(ready?' download-ready':'')+(selected?' selected':'');if(count||ready){cells+='<button type="button" class="'+classes+'" data-calendar-day="'+esc(key)+'" aria-label="'+esc(key)+(count?' · '+count+' jobbsökningar':'')+(ready?' · månadsfil klar':'')+'"><span class="calendar-number">'+day+'</span>'+(count?'<span class="calendar-count">'+count+' sökt'+(count===1?'':'a')+'</span>':'')+(ready?'<span class="calendar-download-marker">TXT klar</span>':'')+'</button>';}else{cells+='<div class="'+classes+'"><span class="calendar-number">'+day+'</span></div>';}}var selection='';if(reportCalendarSelectedDay){var selectedCount=counts[reportCalendarSelectedDay]||0;if(reportCalendarSelectedDay===readyDay&&exportRow){selection='<div class="calendar-selection"><p><strong>'+esc(reportCalendarSelectedDay)+'</strong> · månadsfilen är klar med '+esc(exportRow.item_count)+' jobb.</p><a class="button" href="/api/reports/'+encodeURIComponent(month)+'/export.txt" download>Ladda ner .txt</a></div>';}else if(selectedCount){selection='<div class="calendar-selection"><p><strong>'+esc(reportCalendarSelectedDay)+'</strong> · '+esc(selectedCount)+' verifierade jobbsökningar den dagen.</p><p class="muted">Nedladdningsknappen visas på dagen då månadsfilen blev klar.</p></div>';}}return '<div class="card activity-calendar"><div class="calendar-head"><button type="button" class="secondary calendar-nav" data-calendar-month="'+esc(months[idx-1]||'')+'" '+(idx<=0?'disabled':'')+' aria-label="Föregående månad">←</button><h3>'+esc(calendarMonthLabel(month))+'</h3><button type="button" class="secondary calendar-nav" data-calendar-month="'+esc(months[idx+1]||'')+'" '+(idx>=months.length-1?'disabled':'')+' aria-label="Nästa månad">→</button></div><div class="calendar-legend"><span><i class="calendar-dot application"></i>Jobbsökning</span><span><i class="calendar-dot download"></i>.txt klar för nedladdning</span></div><div class="calendar-weekdays" aria-hidden="true"><span>Mån</span><span>Tis</span><span>Ons</span><span>Tor</span><span>Fre</span><span>Lör</span><span>Sön</span></div><div class="calendar-grid">'+cells+'</div>'+selection+'</div>';}
function setupActivityCalendar(d){document.querySelectorAll('[data-calendar-month]').forEach(function(b){b.onclick=function(){if(!b.dataset.calendarMonth)return;reportCalendarMonth=b.dataset.calendarMonth;reportCalendarSelectedDay='';renderReport(d);};});document.querySelectorAll('[data-calendar-day]').forEach(function(b){b.onclick=function(){reportCalendarSelectedDay=b.dataset.calendarDay||'';renderReport(d);};});}
function renderReport(d){var rows=d.reportActivities.length?d.reportActivities.map(function(i){return '<tr><td>'+badge(i.state)+'</td><td>'+esc(i.title)+'<br><code>'+esc(i.external_id)+'</code></td><td>'+esc(i.employer||'')+'</td><td>'+esc(i.location||i.country_code||'')+'</td><td>'+when(i.applied_at)+'</td><td class="error">'+esc(i.last_error||'')+'</td></tr>';}).join(''):'<tr><td colspan="6" class="empty">Inga rapportposter ännu.</td></tr>';document.querySelector('[data-panel=report]').innerHTML='<div class="grid"><div class="card"><h2>Rapport '+esc(d.reportMonth)+'</h2>'+(d.report?badge(reportState(d.report)):'<span class="muted">Inte skapad än</span>')+'<p>'+esc(d.reportSaved)+'/'+esc(d.target)+' sparade</p><p class="'+reportMessageClass(d.report)+'">'+esc(d.report&&d.report.last_error||'')+'</p></div><div class="card"><h2>Månadsfiler</h2><p>En .txt skapas och sparas automatiskt när '+esc(d.target)+' verifierade jobb finns för månaden.</p><p class="muted">Filen innehåller Jobbsök-ID, yrkesroll, stad och omfattning. Datum tas inte med.</p></div></div>'+renderActivityCalendar(d)+'<div class="card"><h2>Aktiviteter</h2><div class="table-wrap"><table><thead><tr><th>Status</th><th>Jobb</th><th>Arbetsgivare</th><th>Ort</th><th>Ansökt</th><th>Fel</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';setupActivityCalendar(d);}

function renderSystem(d){var c=d.configuration;var checks=checkRow('StudentConsulting-konto',c.studentConsultingCredentials,c.studentConsultingCredentialsSource)+checkRow('Autosubmit',c.studentConsultingAutoSubmit,c.studentConsultingAutoSubmitSource)+'<div class="notice"><span>Jobbkälla<br><span class="source">StudentConsulting-profil</span></span><strong class="ok">Matcha jobb</strong></div>'+'<div class="notice"><span>Extra lämplighetsfilter<br><span class="source">'+esc(c.suitabilityPolicy?sourceLabel(c.suitabilityPolicySource):'Valfritt')+'</span></span><strong class="ok">'+(c.suitabilityPolicy?'Aktivt':'Valfritt')+'</strong></div>'+checkRow('BankID-notifiering',c.bankIdNotification,c.bankIdNotificationSource);var storageWarning=!c.managedConfigurationStorageReady?'<div class="card bankid-callout"><h2>Konfigurationslagret är inte initierat</h2><p>D1-migration <code>0006_runtime_configuration.sql</code> måste appliceras av en auktoriserad Cloudflare-identitet innan konfigurationen kan sparas. Dashboarden och automationen fortsätter fail-closed under tiden.</p></div>':'';var recovery=c.managedConfigurationUnreadable?'<div class="card bankid-callout"><h2>Konfigurationen behöver sparas om</h2><p>Den tidigare dashboard-konfigurationen kan inte dekrypteras, till exempel efter en OAuth-hemlighetsrotation. Fyll i nödvändiga värden nedan och spara för att ersätta den.</p></div>':'';var n=d.notifications.length?d.notifications.map(function(x){return '<tr><td>'+when(x.created_at)+'</td><td>'+esc(x.kind)+'</td><td>'+esc(x.channel)+'</td><td>'+badge(x.status)+'</td><td><code>'+esc(x.automation_run_id)+'</code></td><td class="error">'+esc(x.error_message||'')+'</td></tr>';}).join(''):'<tr><td colspan="6" class="empty">Inga notifieringar sparade.</td></tr>';var credentialPlaceholder=c.studentConsultingCredentials?'Konfigurerat – fyll båda fälten för att ersätta':'Krävs för StudentConsulting';var webhookPlaceholder=c.notifyWebhookConfigured?'Konfigurerad – lämna tomt för att behålla':'https://…';var form='<form id="runtimeConfigForm"><div class="config-section"><h2>StudentConsulting</h2><div class="form-grid"><label class="field"><span>E-post</span><input id="cfgStudentEmail" type="email" autocomplete="username" placeholder="'+esc(credentialPlaceholder)+'"></label><label class="field"><span>Lösenord</span><input id="cfgStudentPassword" type="password" autocomplete="current-password" placeholder="'+esc(credentialPlaceholder)+'"></label></div><label class="check-row"><input id="cfgAutoSubmit" type="checkbox" '+(c.studentConsultingAutoSubmit?'checked':'')+'><span>Tillåt autosubmit när alla lämplighets- och quota-kontroller är godkända</span></label></div><div class="config-section"><h2>Extra lämplighetsfilter (valfritt)</h2><p class="config-note">Jobb hämtas från din inloggade StudentConsulting-vy <strong>Matcha jobb</strong>. Fälten nedan begränsar urvalet ytterligare men behövs inte för autosubmit.</p><div class="form-grid"><label class="field"><span>Måste innehålla (valfritt)</span><textarea id="cfgInclude" placeholder="supporttekniker,it-support,helpdesk">'+esc(c.jobIncludeTerms)+'</textarea></label><label class="field"><span>Får inte innehålla</span><textarea id="cfgExclude" placeholder="chef,senior">'+esc(c.jobExcludeTerms)+'</textarea></label><label class="field"><span>Tillåtna orter</span><input id="cfgLocations" value="'+esc(c.jobAllowedLocations)+'" placeholder="Stockholm,Uppsala"></label><label class="field"><span>Tillåtna länder</span><input id="cfgCountries" value="'+esc(c.jobAllowedCountries)+'" placeholder="SE"></label></div></div><div class="config-section"><h2>BankID-notifiering och manuell körning</h2><div class="form-grid"><label class="field"><span>Notifiering till</span><input id="cfgNotifyTo" type="email" value="'+esc(c.notifyEmailTo)+'" placeholder="du@example.com"></label><label class="field"><span>Notifiering från</span><input id="cfgNotifyFrom" type="email" value="'+esc(c.notifyEmailFrom)+'" placeholder="jobb@example.com"></label><label class="field"><span>Webhook, valfri</span><input id="cfgWebhook" type="url" inputmode="url" placeholder="'+esc(webhookPlaceholder)+'"></label></div></div><p class="config-note">StudentConsulting-lösenord och webhook lagras krypterat och returneras aldrig till webbläsaren efter sparning. Värden som redan är satta i deployment har företräde.</p><div class="config-actions"><button id="saveConfig" type="submit">Spara konfiguration</button><span id="configResult" class="muted"></span></div></form>';document.querySelector('[data-panel=system]').innerHTML='<div class="grid"><div class="card"><h2>Runtime-konfiguration</h2>'+checks+'</div><div class="card"><h2>Automation</h2><p>'+esc(d.automaticMode.applicationWindow)+'</p><p>'+esc(d.automaticMode.schedule)+'</p><p class="muted">'+(c.updatedAt?'Dashboardkonfiguration uppdaterad '+when(c.updatedAt):'Ingen dashboardkonfiguration sparad ännu.')+'</p></div></div>'+storageWarning+recovery+'<div class="card">'+form+'</div><div class="card"><h2>Notifieringshistorik</h2><div class="table-wrap"><table><thead><tr><th>Tid</th><th>Typ</th><th>Kanal</th><th>Status</th><th>Körning</th><th>Fel</th></tr></thead><tbody>'+n+'</tbody></table></div></div>';setupConfigForm(c);}
function setupConfigForm(c){var f=document.getElementById('runtimeConfigForm');if(!f)return;if(!c.managedConfigurationStorageReady){f.querySelectorAll('input,textarea,button').forEach(function(el){el.disabled=true;});var blocked=document.getElementById('configResult');if(blocked)blocked.textContent='D1-migration 0006 måste appliceras innan konfiguration kan sparas.';return;}f.oninput=function(){configDirty=true;};f.onchange=function(){configDirty=true;};f.onsubmit=async function(e){e.preventDefault();var out=document.getElementById('configResult'),button=document.getElementById('saveConfig');var email=document.getElementById('cfgStudentEmail').value.trim(),password=document.getElementById('cfgStudentPassword').value;if(Boolean(email)!==Boolean(password)){out.textContent='Fyll både StudentConsulting e-post och lösenord, eller lämna båda tomma.';out.className='bad';return;}var payload={studentConsultingAutoSubmit:document.getElementById('cfgAutoSubmit').checked,jobIncludeTerms:document.getElementById('cfgInclude').value,jobExcludeTerms:document.getElementById('cfgExclude').value,jobAllowedLocations:document.getElementById('cfgLocations').value,jobAllowedCountries:document.getElementById('cfgCountries').value,notifyEmailTo:document.getElementById('cfgNotifyTo').value,notifyEmailFrom:document.getElementById('cfgNotifyFrom').value};if(email&&password)payload.studentConsulting={email:email,password:password};var webhook=document.getElementById('cfgWebhook').value.trim();if(webhook)payload.notifyWebhookUrl=webhook;button.disabled=true;out.className='muted';out.textContent='Sparar…';try{await api('/api/configuration',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});configDirty=false;out.className='ok';out.textContent='Sparat.';setTimeout(load,250);}catch(error){out.className='bad';out.textContent='Kunde inte spara: '+error.message;}finally{button.disabled=false;}};}
async function openRun(id){var dlg=document.getElementById('runDialog'),body=document.getElementById('runBody');body.innerHTML='<div class="empty">Laddar…</div>';dlg.showModal();try{var d=await api('/api/runs/'+encodeURIComponent(id));document.getElementById('runTitle').textContent=id;var apps=d.applications.map(function(a){return '<div class="notice"><span>'+esc(a.title)+' <code>'+esc(a.external_id)+'</code></span>'+badge(a.status)+'</div>';}).join('')||'<div class="empty">Inga ansökningar.</div>';var attempts=d.attempts.map(function(a){return '<tr><td>'+esc(a.attempt_no)+'</td><td><code>'+esc(a.application_id)+'</code></td><td>'+badge(a.status)+'</td><td>'+when(a.started_at)+'</td><td class="error">'+esc(a.error_code||'')+' '+esc(a.error_message||'')+'</td></tr>';}).join('');var attemptCards=d.attempts.map(function(a){var error=[a.error_code,a.error_message].filter(Boolean).join(' ');return '<article class="attempt-card"><div class="run-head">'+badge(a.status)+'<span class="muted">'+when(a.started_at)+'</span></div><div class="run-meta"><span><small>Försök</small>'+esc(a.attempt_no)+'</span><span><small>Ansökan</small><code>'+esc(a.application_id)+'</code></span></div>'+(error?'<p class="error">'+esc(error)+'</p>':'')+'</article>';}).join('');var evidence=d.evidence.map(function(e){return '<div class="notice"><span><strong>'+esc(e.kind)+'</strong><br><code>'+esc(e.object_key)+'</code><br><span class="muted">sha256: '+esc(e.sha256||'inte lagrad')+'</span></span><span>'+when(e.created_at)+'</span></div>';}).join('')||'<div class="empty">Ingen evidensmetadata.</div>';var active=d.run.status==='running'||d.run.status==='needs_user_auth',canDelete=!active&&d.applications.length===0,controls='<div class="toolbar">'+(active?'<button id="stopRun" class="secondary">Stoppa körning</button>':'')+(canDelete?'<button id="deleteRun" class="secondary">Radera körning</button>':'')+'<span id="runActionResult" class="muted"></span></div>';body.innerHTML='<div class="card"><h2>Run</h2>'+badge(runState(d.run))+'<p class="mono">'+esc(d.run.workflow_instance_id||'')+'</p><p class="'+runMessageClass(d.run)+'">'+esc(d.run.last_error||'')+'</p>'+controls+'</div><div class="card"><h2>Ansökningar</h2>'+apps+'</div><div class="card"><h2>Försök</h2><div class="table-wrap attempts-table"><table><tbody>'+attempts+'</tbody></table></div><div class="attempt-cards">'+(attemptCards||'<div class="empty">Inga försök.</div>')+'</div></div><div class="card"><h2>Evidensmetadata</h2>'+evidence+'</div>';var stop=document.getElementById('stopRun');if(stop)stop.onclick=function(){runAction(id,'stop');};var del=document.getElementById('deleteRun');if(del)del.onclick=function(){runAction(id,'delete');};}catch(e){body.innerHTML='<div class="card bad">'+esc(e.message)+'</div>';}}
async function runAction(id,action){var out=document.getElementById('runActionResult'),verb=action==='stop'?'stoppa':'radera';if(!confirm('Vill du '+verb+' den här körningen?'))return;if(out)out.textContent=action==='stop'?'Stoppar…':'Raderar…';try{await api('/api/runs/'+encodeURIComponent(id)+(action==='stop'?'/stop':''),{method:action==='stop'?'POST':'DELETE'});document.getElementById('runDialog').close();await load();}catch(e){if(out)out.textContent=e.message;}}
function setupManual(d){var b=document.getElementById('manual'),out=document.getElementById('manualResult');if(!b||!out)return;var c=d.configuration,activeRun=d.attention.activeRun,targetReached=d.verified>=d.target,currentPrepared=d.reportItems>=Math.min(d.verified,d.target),submissionPending=!d.submissionReport||d.submissionReport.status!=='submitted',applicationReady=c.studentConsultingCredentials&&c.studentConsultingAutoSubmit,ready=d.applicationWindowOpen&&!activeRun&&(targetReached?(!currentPrepared||submissionPending):applicationReady);b.disabled=!ready;b.textContent=targetReached&&!currentPrepared?'Förbered aktivitetskö':targetReached&&submissionPending?'Fortsätt föregående rapport':'Kör nu';if(activeRun){out.textContent='En körning pågår.';return;}if(!d.applicationWindowOpen){out.textContent='Körningsfönstret är stängt.';return;}if(targetReached&&currentPrepared&&!submissionPending){out.textContent='10/10 ansökningar är klara. Aktuella aktiviteter hanteras ovan.';return;}if(targetReached&&!currentPrepared){out.textContent='10/10 ansökningar är klara. Kör en gång för att skapa den aktuella månadens aktivitetskö.';}else if(targetReached&&submissionPending){out.textContent='Den aktuella aktivitetskön är förberedd. Föregående rapport behöver fortfarande bekräftas.';}else if(!applicationReady){out.textContent='Slutför StudentConsulting-konfigurationen först.';return;}b.onclick=async function(){b.disabled=true;out.textContent=' Startar…';try{var r=await api('/api/runs/manual',{method:'POST'});out.textContent=' Startad: '+r.runId;}catch(e){out.textContent=' '+e.message;}finally{setTimeout(load,250);}};}
async function confirmLocalReportSubmitted(){if(!dashboard)return;var r=dashboard.runs.find(function(x){return x.status==='needs_user_auth'&&x.report_month===dashboard.submissionReportMonth;});if(!r)return;var out=document.getElementById('reportSubmittedResult');if(!confirm('Bekräfta endast om Arbetsförmedlingen visar att föregående månads rapport är inskickad.'))return;if(out)out.textContent='Registrerar…';try{var x=await api('/api/runs/'+encodeURIComponent(r.id)+'/report/manual-submitted',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true})});if(out)out.textContent=x.message||'Registrerat.';setTimeout(load,250);}catch(error){if(out)out.textContent='Kunde inte registrera: '+error.message;}}
async function markCurrentReportItemSaved(d,item){var out=document.getElementById('reportItemResult');if(!confirm('Bekräfta att just Jobb-ID '+item.external_id+' är sparat under Sökta jobb hos Arbetsförmedlingen.'))return;if(out)out.textContent='Registrerar…';try{var x=await api('/api/reports/'+encodeURIComponent(d.reportMonth)+'/items/'+encodeURIComponent(item.application_id)+'/saved',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true})});if(out)out.textContent=x.message||'Sparat.';setTimeout(load,250);}catch(error){if(out)out.textContent='Kunde inte registrera: '+error.message;}}
async function load(){try{var d=await api('/api/dashboard');dashboard=d;document.getElementById('freshness').textContent='Uppdaterad '+when(d.generatedAt);renderOverview(d);renderApplications(d);renderRuns(d);renderReport(d);if(!configDirty)renderSystem(d);tab((location.hash||'#overview').slice(1));}catch(e){overviewSignature='';document.querySelector('[data-panel=overview]').innerHTML='<div class="card bad">'+esc(e.message)+'</div>';}}
initTheme();document.querySelectorAll('[data-tab]').forEach(function(a){a.onclick=function(e){e.preventDefault();location.hash=a.dataset.tab;tab(a.dataset.tab);};});window.onhashchange=function(){tab((location.hash||'#overview').slice(1));};document.getElementById('closeRun').onclick=function(){document.getElementById('runDialog').close();};load();setInterval(load,10000);`;
